 private final class Ruler extends View{int w;Paint p=new Paint(1);Ruler(Activity a,int width){super(a);w=width;}protected void onDraw(Canvas c){super.onDraw(c);p.setColor(Color.GRAY);p.setStrokeWidth(dp(1));for(int x=0;x<w;x+=dp(8)){int len=(x%(dp(40))==0)?dp(10):dp(4);c.drawLine(x,0,x,len,p);}}}
 private void search(){EditText e=new EditText(activity);e.setSingleLine(true);new AlertDialog.Builder(activity).setTitle("Найти текст").setView(e).setNegativeButton("Отмена",null).setPositiveButton("Найти",(d,w)->{lastQuery=e.getText().toString().toLowerCase(Locale.ROOT);searchCursor=-1;if(!lastQuery.isEmpty()&&!findNext())Toast.makeText(activity,"Совпадений в текущем окне нет",Toast.LENGTH_SHORT).show();}).show();}
 private boolean findNext(){if(scroll==null||lastQuery.isEmpty())return false;ArrayList<TextView> ms=new ArrayList<>();collect(scroll,lastQuery,ms);if(ms.isEmpty())return false;searchCursor=(searchCursor+1)%ms.size();int[] p=new int[2],s=new int[2];ms.get(searchCursor).getLocationOnScreen(p);scroll.getLocationOnScreen(s);scroll.smoothScrollBy(0,p[1]-s[1]-dp(24));return true;}
 private void collect(View v,String q,ArrayList<TextView> a){if(v instanceof TextView&&((TextView)v).getText().toString().toLowerCase(Locale.ROOT).contains(q))a.add((TextView)v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)collect(g.getChildAt(i),q,a);}}
