 private void goPage(){EditText e=new EditText(activity);e.setInputType(2);e.setHint("1–"+renderedPages.size());new AlertDialog.Builder(activity).setTitle("Страница текущего окна (оценка)").setView(e).setNegativeButton("Отмена",null).setPositiveButton("Открыть",(d,w)->{try{View v=renderedPages.get(Integer.parseInt(e.getText().toString())-1);scroll.smoothScrollTo(0,v.getTop());}catch(Exception x){Toast.makeText(activity,"Страница вне текущего окна",Toast.LENGTH_SHORT).show();}}).show();}
